{{ config(
            materialized='table',
                post_hook={
                    "sql": "delete from maplemonk._airbyte_raw_Shopify_beastlife_hourly_ORDERS where cast(CAST(JSON_VALUE(_airbyte_data, \'$.created_at\') AS timestamp) as date) < CURRENT_DATE(\"Asia/Kolkata\") - 2 ; create or replace table maplemonk.shopify_hourly_beastlife_orders as SELECT CAST(JSON_VALUE(_airbyte_data, \'$.id\') AS INT64) AS id, JSON_VALUE(_airbyte_data, \'$.admin_graphql_api_id\') AS admin_graphql_api_id, CAST(JSON_VALUE(_airbyte_data, \'$.app_id\') AS INT64) AS app_id, JSON_VALUE(_airbyte_data, \'$.browser_ip\') AS browser_ip, CAST(JSON_VALUE(_airbyte_data, \'$.buyer_accepts_marketing\') AS BOOL) AS buyer_accepts_marketing, JSON_VALUE(_airbyte_data, \'$.cancel_reason\') AS cancel_reason, CAST(JSON_VALUE(_airbyte_data, \'$.cancelled_at\') AS TIMESTAMP) AS cancelled_at, JSON_VALUE(_airbyte_data, \'$.cart_token\') AS cart_token, CAST(JSON_VALUE(_airbyte_data, \'$.checkout_id\') AS INT64) AS checkout_id, JSON_VALUE(_airbyte_data, \'$.checkout_token\') AS checkout_token, JSON_QUERY(_airbyte_data, \'$.client_details\') AS client_details, CAST(JSON_VALUE(_airbyte_data, \'$.closed_at\') AS TIMESTAMP) AS closed_at, JSON_VALUE(_airbyte_data, \'$.confirmation_number\') AS confirmation_number, CAST(JSON_VALUE(_airbyte_data, \'$.confirmed\') AS BOOL) AS confirmed, JSON_VALUE(_airbyte_data, \'$.contact_email\') AS contact_email, CAST(JSON_VALUE(_airbyte_data, \'$.created_at\') AS TIMESTAMP) AS created_at, JSON_VALUE(_airbyte_data, \'$.currency\') AS currency, CAST(JSON_VALUE(_airbyte_data, \'$.current_subtotal_price\') AS FLOAT64) AS current_subtotal_price, JSON_QUERY(_airbyte_data, \'$.current_subtotal_price_set\') AS current_subtotal_price_set, JSON_QUERY(_airbyte_data, \'$.current_total_additional_fees_set\') AS current_total_additional_fees_set, CAST(JSON_VALUE(_airbyte_data, \'$.current_total_discounts\') AS FLOAT64) AS current_total_discounts, JSON_QUERY(_airbyte_data, \'$.current_total_discounts_set\') AS current_total_discounts_set, JSON_QUERY(_airbyte_data, \'$.current_total_duties_set\') AS current_total_duties_set, CAST(JSON_VALUE(_airbyte_data, \'$.current_total_price\') AS FLOAT64) AS current_total_price, JSON_QUERY(_airbyte_data, \'$.current_total_price_set\') AS current_total_price_set, CAST(JSON_VALUE(_airbyte_data, \'$.current_total_tax\') AS FLOAT64) AS current_total_tax, JSON_QUERY(_airbyte_data, \'$.current_total_tax_set\') AS current_total_tax_set, JSON_VALUE(_airbyte_data, \'$.customer_locale\') AS customer_locale, JSON_VALUE(_airbyte_data, \'$.device_id\') AS device_id, JSON_QUERY(_airbyte_data, \'$.discount_codes\') AS discount_codes, CAST(JSON_VALUE(_airbyte_data, \'$.duties_included\') AS BOOL) AS duties_included, JSON_VALUE(_airbyte_data, \'$.email\') AS email, CAST(JSON_VALUE(_airbyte_data, \'$.estimated_taxes\') AS BOOL) AS estimated_taxes, JSON_VALUE(_airbyte_data, \'$.financial_status\') AS financial_status, JSON_VALUE(_airbyte_data, \'$.fulfillment_status\') AS fulfillment_status, JSON_VALUE(_airbyte_data, \'$.landing_site\') AS landing_site, JSON_VALUE(_airbyte_data, \'$.landing_site_ref\') AS landing_site_ref, CAST(JSON_VALUE(_airbyte_data, \'$.location_id\') AS INT64) AS location_id, JSON_VALUE(_airbyte_data, \'$.merchant_business_entity_id\') AS merchant_business_entity_id, CAST(JSON_VALUE(_airbyte_data, \'$.merchant_of_record_app_id\') AS INT64) AS merchant_of_record_app_id, JSON_VALUE(_airbyte_data, \'$.name\') AS name, JSON_VALUE(_airbyte_data, \'$.note\') AS note, JSON_QUERY(_airbyte_data, \'$.note_attributes\') AS note_attributes, CAST(JSON_VALUE(_airbyte_data, \'$.number\') AS INT64) AS number, CAST(JSON_VALUE(_airbyte_data, \'$.order_number\') AS INT64) AS order_number, JSON_VALUE(_airbyte_data, \'$.order_status_url\') AS order_status_url, JSON_QUERY(_airbyte_data, \'$.original_total_additional_fees_set\') AS original_total_additional_fees_set, JSON_QUERY(_airbyte_data, \'$.original_total_duties_set\') AS original_total_duties_set, JSON_QUERY(_airbyte_data, \'$.payment_gateway_names\') AS payment_gateway_names, JSON_VALUE(_airbyte_data, \'$.phone\') AS phone, JSON_VALUE(_airbyte_data, \'$.po_number\') AS po_number, JSON_VALUE(_airbyte_data, \'$.presentment_currency\') AS presentment_currency, CAST(JSON_VALUE(_airbyte_data, \'$.processed_at\') AS TIMESTAMP) AS processed_at, JSON_VALUE(_airbyte_data, \'$.reference\') AS reference, JSON_VALUE(_airbyte_data, \'$.referring_site\') AS referring_site, JSON_VALUE(_airbyte_data, \'$.source_identifier\') AS source_identifier, JSON_VALUE(_airbyte_data, \'$.source_name\') AS source_name, JSON_VALUE(_airbyte_data, \'$.source_url\') AS source_url, CAST(JSON_VALUE(_airbyte_data, \'$.subtotal_price\') AS FLOAT64) AS subtotal_price, JSON_QUERY(_airbyte_data, \'$.subtotal_price_set\') AS subtotal_price_set, JSON_VALUE(_airbyte_data, \'$.tags\') AS tags, CAST(JSON_VALUE(_airbyte_data, \'$.tax_exempt\') AS BOOL) AS tax_exempt, JSON_QUERY(_airbyte_data, \'$.tax_lines\') AS tax_lines, CAST(JSON_VALUE(_airbyte_data, \'$.taxes_included\') AS BOOL) AS taxes_included, CAST(JSON_VALUE(_airbyte_data, \'$.test\') AS BOOL) AS test, JSON_VALUE(_airbyte_data, \'$.token\') AS token, JSON_QUERY(_airbyte_data, \'$.total_cash_rounding_payment_adjustment_set\') AS total_cash_rounding_payment_adjustment_set, JSON_QUERY(_airbyte_data, \'$.total_cash_rounding_refund_adjustment_set\') AS total_cash_rounding_refund_adjustment_set, CAST(JSON_VALUE(_airbyte_data, \'$.total_discounts\') AS FLOAT64) AS total_discounts, JSON_QUERY(_airbyte_data, \'$.total_discounts_set\') AS total_discounts_set, CAST(JSON_VALUE(_airbyte_data, \'$.total_line_items_price\') AS FLOAT64) AS total_line_items_price, JSON_QUERY(_airbyte_data, \'$.total_line_items_price_set\') AS total_line_items_price_set, CAST(JSON_VALUE(_airbyte_data, \'$.total_outstanding\') AS FLOAT64) AS total_outstanding, CAST(JSON_VALUE(_airbyte_data, \'$.total_price\') AS FLOAT64) AS total_price, JSON_QUERY(_airbyte_data, \'$.total_price_set\') AS total_price_set, JSON_QUERY(_airbyte_data, \'$.total_shipping_price_set\') AS total_shipping_price_set, CAST(JSON_VALUE(_airbyte_data, \'$.total_tax\') AS FLOAT64) AS total_tax, JSON_QUERY(_airbyte_data, \'$.total_tax_set\') AS total_tax_set, CAST(JSON_VALUE(_airbyte_data, \'$.total_tip_received\') AS FLOAT64) AS total_tip_received, CAST(JSON_VALUE(_airbyte_data, \'$.total_weight\') AS INT64) AS total_weight, CAST(JSON_VALUE(_airbyte_data, \'$.updated_at\') AS TIMESTAMP) AS updated_at, CAST(JSON_VALUE(_airbyte_data, \'$.user_id\') AS INT64) AS user_id, JSON_QUERY(_airbyte_data, \'$.billing_address\') AS billing_address, JSON_QUERY(_airbyte_data, \'$.customer\') AS customer, JSON_QUERY(_airbyte_data, \'$.discount_applications\') AS discount_applications, JSON_QUERY(_airbyte_data, \'$.fulfillments\') AS fulfillments, JSON_QUERY(_airbyte_data, \'$.line_items\') AS line_items, JSON_QUERY(_airbyte_data, \'$.payment_terms\') AS payment_terms, JSON_QUERY(_airbyte_data, \'$.refunds\') AS refunds, JSON_QUERY(_airbyte_data, \'$.shipping_address\') AS shipping_address, JSON_QUERY(_airbyte_data, \'$.shipping_lines\') AS shipping_lines, JSON_VALUE(_airbyte_data, \'$.shop_url\') AS shop_url, _airbyte_emitted_at, _airbyte_ab_id from( select *, row_number() over (partition by JSON_VALUE(_airbyte_data, \'$.id\') order by _airbyte_emitted_at desc) rw from maplemonk._airbyte_raw_Shopify_beastlife_hourly_ORDERS ) where rw = 1 ; CREATE TABLE IF NOT EXISTS maplemonk.hourly_UTM_Mapping ( UTM_Source STRING, UTM_Medium STRING, Channel STRING, Source STRING ) ; CREATE TABLE IF NOT EXISTS maplemonk.SKU_MASTER ( SKUCODE STRING, NAME STRING, CATEGORY STRING, SUB_CATEGORY STRING ) ; create table if not exists maplemonk.Shopify_hourly_beastlife_dev_UTM_Parameters (ID STRING ,NAME STRING ,CREATEDAT STRING ,CUSTOMERJOURNEY STRING ,CUSTOMERJOURNEYSUMMARY STRING ,REFERRERURL STRING ,REFERRALCODE STRING ,LANDINGPAGEURL STRING ,REFERRERDISPLAYTEXT STRING ,LANDINGPAGEDISPLAYTEXT STRING ); create or replace table maplemonk.beastlife_Shopify_hourly_UTM_Parameters as select ShopifyQL.* ,upper(coalesce(UTM_MAPPING.CHANNEL,ShopifyQL.ShopifyQL_Unmapped_Last_Source, UTM_MAPPING_REF.CHANNEL)) as ShopifyQL_MAPPED_CHANNEL ,upper(coalesce(UTM_MAPPING.SOURCE,ShopifyQL.ShopifyQL_Unmapped_Last_Source,UTM_MAPPING_REF.SOURCE)) as ShopifyQL_MAPPED_SOURCE from (select * from ( select A.id ,A.name ,A.createdat ,cast (JSON_EXTRACT_SCALAR(A.customerjourneysummary,\'$.momentsCount\') as int) Moments_Count ,cast (JSON_EXTRACT_SCALAR(A.customerjourneysummary,\'$.daysToConversion\') as int) DaysToConvert ,cast (JSON_EXTRACT_SCALAR(A.customerjourneysummary,\'$.lastVisit.utmParameters.source\') as string) LastVisit_UTM_Source ,cast (JSON_EXTRACT_SCALAR(A.customerjourneysummary,\'$.lastVisit.utmParameters.medium\') as string) LastVisit_UTM_Medium ,cast (JSON_EXTRACT_SCALAR(A.customerjourneysummary,\'$.lastVisit.source\') as string) LastVisit_NON_UTM_Source ,cast (JSON_EXTRACT_SCALAR(A.customerjourneysummary,\'$.lastVisit.utmParameters.campaign\') as string) LastVisit_UTM_Campaign ,cast (JSON_EXTRACT_SCALAR(A.customerjourneysummary,\'$.firstVisit.utmParameters.source\') as string) FirstVisit_UTM_Source ,cast (JSON_EXTRACT_SCALAR(A.customerjourneysummary,\'$.firstVisit.utmParameters.medium\') as string) FirstVisit_UTM_Medium ,cast (JSON_EXTRACT_SCALAR(A.customerjourneysummary,\'$.firstVisit.utmParameters.campaign\') as string) FirstVisit_UTM_Campaign ,replace(JSON_EXTRACT_SCALAR(b,\'$.id\') ,\'gid://shopify/CustomerVisit/\',\'\') Moment_ID ,JSON_EXTRACT_SCALAR(b,\'$.utmParameters.source\') Last_Moment_UTM_Source ,JSON_EXTRACT_SCALAR(b,\'$.utmParameters.medium\') Last_Moment_UTM_Medium ,case when cast (JSON_EXTRACT_SCALAR(A.customerjourneysummary,\'$.momentsCount\') as int) >1 then cast (JSON_EXTRACT_SCALAR(A.customerjourneysummary,\'$.lastVisit.utmParameters.source\') as string) else cast (JSON_EXTRACT_SCALAR(A.customerjourneysummary,\'$.firstVisit.utmParameters.source\') as string) end CJSummary_utm_source ,referrerdisplaytext Referrer_Name ,customerjourneysummary ,customerjourney ,coalesce(JSON_EXTRACT_SCALAR(b,\'$.utmParameters.source\') ,cast (JSON_EXTRACT_SCALAR(A.customerjourneysummary,\'$.lastVisit.utmParameters.source\') as string) ,cast (JSON_EXTRACT_SCALAR(A.customerjourneysummary,\'$.lastVisit.source\') as string) ) ShopifyQL_Unmapped_Last_Source ,coalesce(JSON_EXTRACT_SCALAR(b,\'$.utmParameters.medium\') ,cast (JSON_EXTRACT_SCALAR(A.customerjourneysummary,\'$.lastVisit.utmParameters.medium\') as string) ) ShopifyQL_Unmapped_Last_Medium ,rank() over (partition by A.name order by replace(JSON_EXTRACT_SCALAR(b,\'$.id\') ,\'gid://shopify/CustomerVisit/\',\'\') desc) rw from maplemonk.Shopify_beastlife_hourly_UTM_Parameters A left join unnest(JSON_EXTRACT_ARRAY(JSON_EXTRACT(customerjourney, \'$.moments\'))) b ) where rw=1 ) ShopifyQL left join (select * from (select * , row_number() over (partition by lower(concat(ifnull(utm_source,\'\'),ifnull(utm_medium,\'\'))) order by 1) rw from maplemonk.hourly_UTM_Mapping ) where rw=1 and lower(concat(ifnull(utm_source,\'\'),ifnull(utm_medium,\'\'))) is not null ) UTM_MAPPING on lower(concat(ifnull(ShopifyQL.ShopifyQL_Unmapped_Last_Source,\'\'),ifnull(ShopifyQL_Unmapped_Last_Medium,\'\'))) = lower(concat(ifnull(UTM_MAPPING.utm_source,\'\'),ifnull(UTM_MAPPING.utm_medium,\'\'))) left join (select * from (select * , row_number() over (partition by lower(utm_source) order by 1) rw from maplemonk.hourly_UTM_Mapping) where rw=1 and UTM_Source is not null ) UTM_MAPPING_REF on lower(ShopifyQL.referrer_name) = lower(UTM_MAPPING_REF.utm_source) ; create or replace table maplemonk.beastlife_hourly_CHECKOUT_SOURCE as With CHECKOUT as ( WITH utm_source_cte AS ( SELECT S.id, UPPER(JSON_EXTRACT_SCALAR(A,\'$.value\') ) AS utm_source FROM maplemonk.shopify_hourly_beastlife_orders S left join UNNEST(JSON_EXTRACT_ARRAY(S.note_attributes)) AS A WHERE (LOWER(note_attributes) LIKE \'%gokwik%\' OR LOWER(note_attributes) LIKE \'%shopflo%\' OR LOWER(S.tags) LIKE \'%gokwik%\' OR LOWER(S.tags) LIKE \'%shopflo%\') AND LOWER(JSON_EXTRACT_SCALAR(A,\'$.name\')) = \'utm_source\' ), utm_medium_cte AS ( SELECT S.id, UPPER(JSON_EXTRACT_SCALAR(A,\'$.value\') ) AS utm_medium FROM maplemonk.shopify_hourly_beastlife_orders S left join UNNEST(JSON_EXTRACT_ARRAY(S.note_attributes)) AS A WHERE (LOWER(note_attributes)LIKE \'%gokwik%\' OR LOWER(note_attributes) LIKE \'%shopflo%\' OR LOWER(S.tags) LIKE \'%gokwik%\' OR LOWER(S.tags) LIKE \'%shopflo%\') AND LOWER(JSON_EXTRACT_SCALAR(A,\'$.name\')) = \'utm_medium\' ), utm_campaign_cte AS ( SELECT S.id, UPPER(JSON_EXTRACT_SCALAR(A,\'$.value\') ) AS utm_campaign FROM maplemonk.shopify_hourly_beastlife_orders S left join UNNEST(JSON_EXTRACT_ARRAY(S.note_attributes)) AS A WHERE (LOWER(note_attributes) LIKE \'%gokwik%\' OR LOWER(note_attributes) LIKE \'%shopflo%\' OR LOWER(S.tags) LIKE \'%gokwik%\' OR LOWER(S.tags) LIKE \'%shopflo%\') AND LOWER(JSON_EXTRACT_SCALAR(A,\'$.name\')) = \'utm_campaign\' ), utm_content_cte AS ( SELECT S.id, UPPER(JSON_EXTRACT_SCALAR(A,\'$.value\') ) AS utm_content FROM maplemonk.shopify_hourly_beastlife_orders S left join UNNEST(JSON_EXTRACT_ARRAY(S.note_attributes)) AS A WHERE (LOWER(note_attributes) LIKE \'%gokwik%\' OR LOWER(note_attributes) LIKE \'%shopflo%\' OR LOWER(S.tags) LIKE \'%gokwik%\' OR LOWER(S.tags) LIKE \'%shopflo%\') AND LOWER(JSON_EXTRACT_SCALAR(A,\'$.name\')) = \'utm_content\' ), utm_term_cte AS ( SELECT S.id, UPPER(JSON_EXTRACT_SCALAR(A,\'$.value\') ) AS utm_term FROM maplemonk.shopify_hourly_beastlife_orders S left join UNNEST(JSON_EXTRACT_ARRAY(S.note_attributes)) AS A WHERE (LOWER(note_attributes) LIKE \'%gokwik%\' OR LOWER(note_attributes) LIKE \'%shopflo%\' OR LOWER(S.tags) LIKE \'%gokwik%\' OR LOWER(S.tags) LIKE \'%shopflo%\') AND LOWER(JSON_EXTRACT_SCALAR(A,\'$.name\')) = \'utm_term\' ) SELECT S.id, S.tags, source_cte.utm_source AS CHECKOUT_UTM_SOURCE, medium_cte.utm_medium AS CHECKOUT_UTM_MEDIUM, campaign_cte.utm_campaign AS CHECKOUT_UTM_CAMPAIGN, content_cte.utm_content AS CHECKOUT_UTM_CONTENT, term_cte.utm_term as checkout_utm_term FROM maplemonk.shopify_hourly_beastlife_orders S LEFT JOIN utm_source_cte source_cte ON S.id = source_cte.id LEFT JOIN utm_medium_cte medium_cte ON S.id = medium_cte.id LEFT JOIN utm_campaign_cte campaign_cte ON S.id = campaign_cte.id LEFT JOIN utm_content_cte content_cte ON S.id = content_cte.id LEFT JOIN utm_term_cte term_cte ON S.id = term_cte.id where (LOWER(note_attributes) LIKE \'%gokwik%\' OR LOWER(note_attributes) LIKE \'%shopflo%\' OR LOWER(S.tags) LIKE \'%gokwik%\' OR LOWER(S.tags) LIKE \'%shopflo%\') ) Select CHECKOUT.* ,coalesce(Upper(UTM_MAPPING.CHANNEL), upper(CHECKOUT_UTM_SOURCE),\'DIRECT\') as CHECKOUT_MAPPED_CHANNEL ,coalesce(Upper(UTM_MAPPING.SOURCE), upper(CHECKOUT_UTM_MEDIUM),\'DIRECT\') as CHECKOUT_MAPPED_SOURCE from CHECKOUT left join (select * from (select * , row_number() over (partition by lower(concat(ifnull(utm_source,\'\'),ifnull(utm_medium,\'\'))) order by 1) rw from maplemonk.hourly_utm_mapping) where rw=1 and lower(concat(ifnull(utm_source,\'\'),ifnull(utm_medium,\'\'))) is not null ) UTM_MAPPING on lower(concat(ifnull(CHECKOUT.CHECKOUT_UTM_SOURCE,\'\'),ifnull(CHECKOUT_UTM_MEDIUM,\'\'))) = lower(concat(ifnull(UTM_MAPPING.utm_source,\'\'),ifnull(UTM_MAPPING.utm_medium,\'\'))) ; CREATE OR REPLACE TABLE maplemonk.Shopify_hourly_All_customers AS select *,\'WEBSITE\' AS Shop_Name from maplemonk.Shopify_beastlife_CUSTOMERS ; create or replace table maplemonk.Shopify_hourly_All_orders as select AO.* ,UPPER(ShopifyQL.shopifyql_mapped_channel) shopifyql_mapped_channel ,UPPER(ShopifyQL.shopifyql_mapped_source) shopifyql_mapped_source ,UPPER(ShopifyQL.FIRSTVISIT_UTM_SOURCE) Shopifyql_FIRSTVISIT_UTM_SOURCE ,UPPER(ShopifyQL.FirstVisit_UTM_Campaign) Shopifyql_FIRSTVISIT_UTM_CAMPAIGN ,upper(ShopifyQL.LastVisit_UTM_Campaign) Shopifyql_LAST_VISIT_UTM_CAMPAIGN ,upper(ShopifyQL.LastVisit_UTM_Medium) Shopifyql_LAST_VISIT_UTM_medium ,UPPER(ShopifyQL.LAST_MOMENT_UTM_SOURCE) Shopifyql_LAST_MOMENT_UTM_SOURCE ,UPPER(ShopifyQL.LastVisit_NON_UTM_Source) Shopifyql_LAST_VISIT_NON_UTM_SOURCE ,UPPER(ShopifyQL.LAST_MOMENT_UTM_MEDIUM) Shopifyql_LAST_MOMENT_UTM_MEDIUM ,UPPER(ShopifyQL.FIRSTVISIT_UTM_MEDIUM) Shopifyql_FIRSTVISIT_UTM_MEDIUM ,safe_divide(ShopifyQL.MOMENTS_COUNT,count(1) over (partition by AO.name order by 1)) MOMENTS_COUNT ,safe_divide(ShopifyQL.DAYSTOCONVERT,count(1) over (partition by AO.name order by 1)) DAYSTOCONVERT ,upper(ShopifyQL_Unmapped_Last_Source) ShopifyQL_Unmapped_Last_Source ,upper(ShopifyQL_Unmapped_Last_Medium) ShopifyQL_Unmapped_Last_Medium ,UPPER(CHECKOUT.CHECKOUT_UTM_SOURCE) CHECKOUT_UTM_SOURCE ,UPPER(CHECKOUT.CHECKOUT_UTM_MEDIUM) CHECKOUT_UTM_MEDIUM ,UPPER(CHECKOUT.CHECKOUT_UTM_CONTENT) CHECKOUT_UTM_CONTENT ,upper(checkout.checkout_utm_term) checout_utm_term ,UPPER(CHECKOUT.CHECKOUT_MAPPED_CHANNEL) CHECKOUT_MAPPED_CHANNEL ,UPPER(CHECKOUT.CHECKOUT_MAPPED_SOURCE) CHECKOUT_MAPPED_SOURCE ,UPPER(Referrer_Name) Referrer_Name ,UPPER(CHECKOUT.CHECKOUT_UTM_CAMPAIGN) CHECKOUT_UTM_CAMPAIGN ,UPPER(coalesce(LastVisit_UTM_Campaign,CHECKOUT_UTM_CAMPAIGN)) FINAL_UTM_CAMPAIGN ,Upper(coalesce(shopifyql_mapped_source,CHECKOUT_MAPPED_SOURCE,ShopifyQL.ShopifyQL_Unmapped_Last_Source,\'Direct\')) FINAL_UTM_SOURCE ,Upper(coalesce(shopifyql_mapped_channel,CHECKOUT_MAPPED_CHANNEL,ShopifyQL.ShopifyQL_Unmapped_Last_Source,\'Direct\')) FINAL_UTM_CHANNEL ,upper(coalesce(ShopifyQL.LastVisit_UTM_Medium, CHECKOUT.CHECKOUT_UTM_MEDIUM, ShopifyQL_Unmapped_Last_Medium, ShopifyQL.LAST_MOMENT_UTM_MEDIUM, ShopifyQL.FIRSTVISIT_UTM_MEDIUM )) final_utm_medium ,upper(checkout.checkout_utm_term) final_utm_term ,coalesce(JSON_EXTRACT_SCALAR(AO.SHIPPING_ADDRESS,\'$.zip\'),JSON_EXTRACT_SCALAR(AO.billing_address,\'$.zip\')) as pincode from (select *,\'WEBSITE\' AS Shop_Name from maplemonk.shopify_hourly_beastlife_orders) AO left join maplemonk.beastlife_Shopify_hourly_UTM_Parameters ShopifyQL on AO.name = ShopifyQL.name left join maplemonk.beastlife_hourly_CHECKOUT_SOURCE CHECKOUT on cast(AO.ID as string) = cast(CHECKOUT.ID as string) ; CREATE OR REPLACE TABLE maplemonk.Shopify_hourly_All_products AS select *,\'WEBSITE\' AS Shop_Name from maplemonk.shopify_beastlife_products ; CREATE OR REPLACE TABLE maplemonk.Shopify_hourly_All_products_variants AS select *,\'WEBSITE\' AS Shop_Name from maplemonk.Shopify_beastlife_dev_PRODUCTS_VARIANTS ; CREATE OR REPLACE TABLE maplemonk.Shopify_hourly_All_customers_addresses AS select *,\'WEBSITE\' AS Shop_Name from maplemonk.Shopify_beastlife_dev_CUSTOMERS_ADDRESSES ; CREATE OR REPLACE TABLE maplemonk.Shopify_hourly_All_orders_items_discount AS WITH line_items AS ( SELECT A.id AS order_id, JSON_EXTRACT_SCALAR(item, \'$.id\') AS line_item_id, JSON_EXTRACT_ARRAY(item, \'$.discount_allocations\') AS discount_allocations_json FROM maplemonk.Shopify_hourly_All_orders A, UNNEST(JSON_EXTRACT_ARRAY(A.LINE_ITEMS)) AS item ), discounts AS ( SELECT order_id, line_item_id, SUM(CAST(JSON_EXTRACT_SCALAR(discount, \'$.amount\') AS FLOAT64)) AS discount FROM line_items, UNNEST(discount_allocations_json) AS discount GROUP BY order_id, line_item_id ), discount_codes AS ( SELECT * FROM ( SELECT A.id AS order_id, JSON_EXTRACT_SCALAR(code, \'$.code\') AS discount_codes, ROW_NUMBER() OVER (PARTITION BY A.id ORDER BY 1) AS rn FROM `MAPLEMONK.Shopify_hourly_All_orders` A, UNNEST(JSON_EXTRACT_ARRAY(A.discount_codes)) AS code ) WHERE rn = 1 ) SELECT d.order_id, d.line_item_id, d.discount, dc.discount_codes FROM discounts d LEFT JOIN discount_codes dc ON d.order_id = dc.order_id; CREATE OR REPLACE TABLE maplemonk.Shopify_hourly_All_orders_items_tax AS SELECT order_id, LINE_ITEM_ID, SUM(CAST(JSON_EXTRACT_SCALAR(tax, \'$.price\') AS FLOAT64)) AS tax, AVG(CAST(JSON_EXTRACT_SCALAR(tax, \'$.rate\') AS FLOAT64)) AS Tax_Rate FROM ( SELECT A.id AS order_id, JSON_EXTRACT_SCALAR(item, \'$.id\') AS LINE_ITEM_ID, JSON_EXTRACT_ARRAY(item, \'$.tax_lines\') AS tax_lines_array FROM `maplemonk.Shopify_hourly_All_orders` A, UNNEST(JSON_EXTRACT_ARRAY(A.LINE_ITEMS)) AS item ) AS order_items, UNNEST(order_items.tax_lines_array) AS tax GROUP BY order_id, LINE_ITEM_ID; CREATE OR REPLACE TABLE maplemonk.Shopify_hourly_All_Refunds AS WITH refund_line_items AS ( SELECT JSON_EXTRACT_SCALAR(refunds,\'$.order_id\') as order_id, JSON_EXTRACT_SCALAR(line_items,\'$.line_item_id\') as LINE_ITEM_ID, JSON_EXTRACT_SCALAR(line_items,\'$.created_at\') as refund_date, sum(cast(JSON_EXTRACT_SCALAR(line_items,\'$.quantity\') as float64)) as refund_quantity, sum(cast(JSON_EXTRACT_SCALAR(line_items,\'$.subtotal\') as float64 )) as refund_subtotal, FROM maplemonk.Shopify_hourly_All_orders A left join unnest(JSON_EXTRACT_ARRAY(A.refunds)) refunds left join unnest(JSON_EXTRACT_ARRAY(JSON_EXTRACT(refunds, \'$.refund_line_items\'))) line_items where JSON_EXTRACT_SCALAR(refunds,\'$.order_id\') is not null group by 1,2,3 ), order_adjustments AS ( SELECT JSON_EXTRACT_SCALAR(order_adj,\'$.order_id\') AS order_id, JSON_EXTRACT_SCALAR(refunds, \'$.created_at\') AS adjustment_date, sum(cast(JSON_EXTRACT_SCALAR(order_adj,\'$.amount\') as float64 )) adjustment FROM maplemonk.Shopify_hourly_All_orders A left join unnest(JSON_EXTRACT_ARRAY(A.refunds)) refunds left join unnest(JSON_EXTRACT_ARRAY(JSON_EXTRACT(refunds, \'$.order_adjustments\'))) order_adj group by 1,2 ), adj_refund as ( Select distinct order_id, line_item_id, date from ( select coalesce(rl.order_id,oa.order_id) order_id, rl.line_item_id, case when rl.refund_date = oa.adjustment_date then rl.refund_date else coalesce(oa.adjustment_date, rl.refund_date) end as date from refund_line_items rl full outer join order_adjustments oa on rl.order_id = oa.order_id ) ), refund_summary as ( select ar.order_id, ar.line_item_id, ar.date, ifnull(rl.refund_quantity,0) refund_quantity, ifnull(rl.refund_subtotal,0) refund_subtotal, ifnull(safe_divide(oa.adjustment,count(1) over (partition by ar.order_id, ar.date)),0) as Adjustment_amount, (ifnull(rl.refund_subtotal,0) - ifnull(ifnull(safe_divide(oa.adjustment,count(1) over (partition by ar.order_id, ar.date)),0),0)) Total_Refund from adj_refund ar left join refund_line_items rl on ar.order_id = rl.order_id and ar.date = rl.refund_date and ar.line_item_id = rl.line_item_id left join order_adjustments oa on ar.order_id = oa.order_id and ar.date = oa.adjustment_date ), aggregate_summary AS ( SELECT order_id, line_item_id, date, sum(refund_quantity) AS Refund_Quantity, sum(Total_Refund) AS Refund_Amount, sum(Adjustment_amount) AS Adjustment_Amount, sum(refund_subtotal) AS Refund_Before_Adjustment FROM refund_summary GROUP BY order_id, line_item_id, date ) SELECT asum.order_id, asum.line_item_id, SUM(asum.Refund_Quantity) AS Quantity, SUM(asum.Refund_Amount) AS Amount, SUM(asum.Adjustment_Amount) AS Adjustment_Amount, SUM(asum.Refund_Before_Adjustment) AS Refund_Before_Adjustment, ARRAY_AGG( STRUCT( date AS Refund_Date, CAST(asum.Refund_Quantity AS FLOAT64) AS Refund_Quantity, CAST(asum.Adjustment_Amount AS FLOAT64) AS Adjustment_Amount, CAST(asum.Refund_Amount AS FLOAT64) AS Refund_Amount ) ) AS Refund_Details FROM aggregate_summary asum GROUP BY asum.order_id, asum.line_item_id; CREATE OR REPLACE TABLE maplemonk.Shopify_hourly_All_orders_fulfillment AS WITH UnnestedOrders AS ( SELECT JSON_EXTRACT_SCALAR(fulfillment, \'$.order_id\') AS order_id, JSON_EXTRACT_ARRAY(fulfillment, \'$.line_items\') AS line_item, JSON_EXTRACT_SCALAR(fulfillment, \'$.tracking_number\') AS AWB, JSON_EXTRACT_SCALAR(fulfillment, \'$.tracking_company\') AS Courier, JSON_EXTRACT_SCALAR(fulfillment, \'$.shipment_status\') AS SHIPPING_STATUS, JSON_EXTRACT_SCALAR(fulfillment, \'$.updated_at\') AS shipping_status_update_date, JSON_EXTRACT_SCALAR(fulfillment, \'$.tracking_url\') AS tracking_url, JSON_EXTRACT_SCALAR(fulfillment, \'$.created_at\') AS Shipping_created_at FROM `maplemonk.Shopify_hourly_All_orders`, UNNEST(JSON_EXTRACT_ARRAY(fulfillments)) AS fulfillment where lower(JSON_EXTRACT_SCALAR(fulfillment, \'$.status\')) not like \'%cancel%\' ) select * from ( select us.*,JSON_EXTRACT_SCALAR(li, \'$.id\') AS Line_Item_ID ,row_number() over(partition by order_id ,JSON_EXTRACT_SCALAR(li, \'$.id\') order by cast(shipping_status_update_date as timestamp) desc )rw from UnnestedOrders us left join unnest(line_item) li ) where rw = 1; create or replace table maplemonk.Shopify_hourly_All_orders_shipping_lines_discount as SELECT id as Order_ID, sum(cast(JSON_EXTRACT_SCALAR(da,\'$.amount\') as float64)) AS total_shipping_discount, FROM maplemonk.Shopify_hourly_All_orders left join unnest(JSON_EXTRACT_ARRAY(shipping_lines))sl left join unnest(JSON_EXTRACT_ARRAY(JSON_EXTRACT(sl, \'$.discount_allocations\'))) da group by 1 ; CREATE OR REPLACE TABLE maplemonk.Shopify_hourly_All_orders_items AS WITH CTE AS ( SELECT SHOP_NAME, CAST(ID AS STRING) AS ORDER_ID, NAME AS ORDER_NAME, CUSTOMER, JSON_EXTRACT_SCALAR(CUSTOMER, \'$.default_address.name\') AS NAME, PHONE, EMAIL, TAGS, user_id, JSON_EXTRACT_SCALAR(A, \'$.id\') AS LINE_ITEM_ID, JSON_EXTRACT_SCALAR(A, \'$.sku\') AS SKU, JSON_EXTRACT_SCALAR(A, \'$.product_id\') AS PRODUCT_ID, JSON_EXTRACT_SCALAR(A, \'$.title\') AS PRODUCT_NAME, JSON_EXTRACT_ARRAY(A, \'$.properties\') AS Properties, CURRENCY, CASE WHEN CANCELLED_AT IS NOT NULL THEN \'CANCELLED\' ELSE \'SHOPIFY_PROCESSED\' END AS ORDER_STATUS, DATETIME(FORMAT_TIMESTAMP(\'%Y-%m-%d %H:%M:%S\', created_at, \'Asia/Kolkata\')) AS ORDER_TIMESTAMP, CAST(JSON_EXTRACT_SCALAR(A, \'$.price\') AS FLOAT64) * CAST(JSON_EXTRACT_SCALAR(A, \'$.quantity\') AS FLOAT64) AS LINE_ITEM_SALES, (CAST(JSON_EXTRACT_SCALAR(TOTAL_SHIPPING_PRICE_SET, \'$.presentment_money.amount\') AS FLOAT64) / COUNT(ID) OVER(PARTITION BY ID ORDER BY ID)) AS SHIPPING_PRICE, CAST(JSON_EXTRACT_SCALAR(A, \'$.price\') AS FLOAT64) / (1 + CAST(JSON_EXTRACT_SCALAR(A, \'$.tax_lines.rate\') AS FLOAT64)) AS PRICE_BEFORE_TAX, CAST(JSON_EXTRACT_SCALAR(A, \'$.quantity\') AS INT64) AS QUANTITY, MOMENTS_COUNT, DAYSTOCONVERT, Shopifyql_LAST_VISIT_UTM_CAMPAIGN, Shopifyql_FIRSTVISIT_UTM_CAMPAIGN, SHOPIFYQL_FIRSTVISIT_UTM_SOURCE, SHOPIFYQL_MAPPED_SOURCE, SHOPIFYQL_MAPPED_CHANNEL, SHOPIFYQL_LAST_MOMENT_UTM_SOURCE, Shopifyql_LAST_VISIT_NON_UTM_SOURCE, Shopifyql_LAST_MOMENT_UTM_MEDIUM, Shopifyql_FIRSTVISIT_UTM_MEDIUM, CHECKOUT_UTM_SOURCE, CHECKOUT_UTM_MEDIUM, CHECKOUT_UTM_CAMPAIGN, CHECKOUT_UTM_CONTENT, checout_utm_term, FINAL_UTM_CAMPAIGN, FINAL_UTM_CHANNEL, FINAL_UTM_SOURCE, final_utm_term, final_utm_medium, REFERRER_NAME, CHECKOUT_MAPPED_SOURCE, CHECKOUT_MAPPED_CHANNEL, PAYMENT_GATEWAY_NAMES AS GATEWAY, SHIPPING_ADDRESS, PINCODE, SO.source_name, SO.location_id, CASE WHEN UPPER(tags) LIKE \'%PPCOD%\' THEN \'PARTIAL_PAID\' WHEN ( REGEXP_CONTAINS(UPPER(tags), r\'(^|,)\s*COD(\s*,|$)\') OR UPPER(tags) LIKE \'%COD-%\' OR REGEXP_CONTAINS(UPPER(PAYMENT_GATEWAY_NAMES), r\'COD|CASH\') ) AND UPPER(tags) NOT LIKE \'%GOKWIK_COD_BLOCKING%\' THEN \'COD\' ELSE \'PREPAID\' END AS payment_mode, CASE WHEN ( ( REGEXP_CONTAINS(UPPER(tags), r\'(^|,)\s*COD(\s*,|$)\') OR UPPER(tags) LIKE \'%COD-%\' OR REGEXP_CONTAINS(UPPER(PAYMENT_GATEWAY_NAMES), r\'COD|CASH\') ) AND UPPER(tags) NOT LIKE \'%PPCOD%\' AND UPPER(tags) NOT LIKE \'%GOKWIK_PPCOD_UPI_GAINER%\' AND UPPER(tags) NOT LIKE \'%GOKWIK_COD_BLOCKING%\' )\'%GOKWIK_PPCOD_UPI_GAINER%\' THEN 1 ELSE 0 END AS COD_flag, financial_status, note_attributes FROM `maplemonk.Shopify_hourly_All_orders` SO LEFT JOIN UNNEST(JSON_EXTRACT_ARRAY(LINE_ITEMS)) AS A ) SELECT CTE.*, IFNULL(T.TAX_RATE, 0) AS TAX_RATE, IFNULL(D.DISCOUNT, 0) AS DISCOUNT, D.discount_codes, CTE.LINE_ITEM_SALES AS GROSS_SALES_AFTER_TAX, CTE.LINE_ITEM_SALES / (1 + IFNULL(T.TAX_RATE, 0)) AS GROSS_SALES_BEFORE_TAX, CASE WHEN IFNULL(T.TAX, 0) = 0 THEN IFNULL(D.DISCOUNT, 0) ELSE IFNULL(D.DISCOUNT, 0) / (1 + IFNULL(T.TAX_RATE, 0)) END AS DISCOUNT_BEFORE_TAX, CASE WHEN IFNULL(T.TAX, 0) = 0 THEN CTE.LINE_ITEM_SALES - IFNULL(D.DISCOUNT, 0) ELSE CTE.LINE_ITEM_SALES / (1 + IFNULL(T.TAX_RATE, 0)) - IFNULL(D.DISCOUNT, 0) / (1 + IFNULL(T.TAX_RATE, 0)) END AS NET_SALES_BEFORE_TAX, IFNULL(T.TAX, 0) AS TAX, CASE WHEN IFNULL(T.TAX, 0) = 0 THEN CTE.LINE_ITEM_SALES - IFNULL(D.DISCOUNT, 0) - safe_divide(IFNULL(SD.TOTAL_SHIPPING_DISCOUNT, 0), COUNT(1) OVER (PARTITION BY CTE.ORDER_ID)) + IFNULL(T.TAX, 0) + CTE.SHIPPING_PRICE ELSE CTE.LINE_ITEM_SALES / (1 + IFNULL(T.TAX_RATE, 0)) - IFNULL(D.DISCOUNT, 0) / (1 + IFNULL(T.TAX_RATE, 0)) - safe_divide(IFNULL(SD.TOTAL_SHIPPING_DISCOUNT, 0), COUNT(1) OVER (PARTITION BY CTE.ORDER_ID)) + IFNULL(T.TAX, 0) + CTE.SHIPPING_PRICE END AS TOTAL_SALES, CASE WHEN R.QUANTITY IS NOT NULL THEN 1 ELSE 0 END AS IS_REFUND, R.REFUND_DETAILS, R.QUANTITY AS REFUND_QUANTITY, R.AMOUNT AS REFUND_VALUE, F.AWB, F.COURIER, F.SHIPPING_STATUS, F.SHIPPING_STATUS_UPDATE_DATE, F.TRACKING_URL, F.SHIPPING_CREATED_AT, safe_divide(IFNULL(SD.TOTAL_SHIPPING_DISCOUNT, 0), COUNT(1) OVER (PARTITION BY CTE.ORDER_ID)) AS TOTAL_SHIPPING_DISCOUNT FROM CTE LEFT JOIN `maplemonk.Shopify_hourly_All_orders_items_tax` T ON cast(CTE.ORDER_ID as string) = CAST(T.ORDER_ID AS STRING) AND cast(CTE.LINE_ITEM_ID as string) = CAST(T.LINE_ITEM_ID AS STRING) LEFT JOIN `maplemonk.Shopify_hourly_All_orders_items_discount` D ON cast(CTE.ORDER_ID as string)= CAST(D.ORDER_ID AS STRING) AND cast(CTE.LINE_ITEM_ID as string) = CAST(D.LINE_ITEM_ID AS STRING) LEFT JOIN `maplemonk.Shopify_hourly_All_Refunds` R ON cast(CTE.ORDER_ID as string) = CAST(R.ORDER_ID AS STRING) AND cast(CTE.LINE_ITEM_ID as string)= CAST(R.LINE_ITEM_ID AS STRING) LEFT JOIN `maplemonk.Shopify_hourly_All_orders_fulfillment` F ON cast(CTE.ORDER_ID as string) = CAST(F.ORDER_ID AS STRING) AND cast(CTE.LINE_ITEM_ID as string) = CAST(F.LINE_ITEM_ID AS STRING) LEFT JOIN `maplemonk.Shopify_hourly_All_orders_shipping_lines_discount` SD ON cast(CTE.ORDER_ID as string) = CAST(SD.ORDER_ID AS STRING); CREATE OR REPLACE TABLE maplemonk.beastlife_hourly_SHOPIFY_FACT_ITEMS_INTERMEDIATE AS SELECT O.SHOP_NAME, COALESCE(O.SHOP_NAME,\'WEBSITE\') AS marketplace, O.ORDER_ID, O.ORDER_NAME, JSON_EXTRACT_SCALAR(O.CUSTOMER, \'$.id\') AS customer_id, O.Name, O.EMAIL, O.PHONE, O.Tags, O.user_id, case when lower(o.tags) like \'%appbrew%\' then \'APP\' else \'WEBSITE\' end app_website_flag, O.LINE_ITEM_ID, O.SKU, o.Properties, O.PRODUCT_ID, O.CURRENCY, O.IS_REFUND, ifnull(TOTAL_SALES,0) - ifnull(REFUND_VALUE,0) as TOTAL_SALES_Ex_Refunds, UPPER(JSON_EXTRACT_SCALAR(O.shipping_address, \'$.city\')) AS shipping_city, UPPER(JSON_EXTRACT_SCALAR(O.shipping_address, \'$.province\')) AS shipping_State, CASE WHEN CD.city IS NULL OR JSON_VALUE(CD.city, \'$\') = \'\' THEN \'NA\' ELSE UPPER(JSON_VALUE(CD.city, \'$\')) END AS city, CASE WHEN CD.province IS NULL OR CD.province = \'\' THEN \'NA\' ELSE UPPER(CD.province) END AS state, CASE WHEN JSON_VALUE(P.title, \'$\') = \'\' THEN \'NA\' ELSE UPPER(JSON_VALUE(P.title, \'$\')) END AS product_name, CASE WHEN JSON_VALUE(P.product_type, \'$\') = \'\' THEN \'NA\' ELSE UPPER(JSON_VALUE(P.product_type, \'$\')) END AS category, O.order_status AS order_status, O.order_timestamp, O.LINE_ITEM_SALES, O.QUANTITY, O.Refund_Quantity, O.Refund_Value, O.TAX, O.TAX_RATE, O.DISCOUNT, O.discount_codes, O.DISCOUNT_BEFORE_TAX, O.GROSS_SALES_AFTER_TAX, O.GROSS_SALES_BEFORE_TAX, O.NET_SALES_BEFORE_TAX, (IFNULL(O.SHIPPING_PRICE, 0) - IFNULL(O.TOTAL_SHIPPING_DISCOUNT, 0)) AS SHIPPING_PRICE, IFNULL(O.TOTAL_SALES, 0) AS TOTAL_SALES, O.MOMENTS_COUNT, O.DAYSTOCONVERT, O.SHOPIFYQL_FIRSTVISIT_UTM_SOURCE, O.SHOPIFYQL_MAPPED_SOURCE, O.SHOPIFYQL_MAPPED_CHANNEL, O.SHOPIFYQL_LAST_MOMENT_UTM_SOURCE, O.Shopifyql_LAST_VISIT_NON_UTM_SOURCE, O.Shopifyql_FIRSTVISIT_UTM_MEDIUM, O.Shopifyql_LAST_MOMENT_UTM_MEDIUM, O.FINAL_UTM_CHANNEL as FINAL_UTM_CHANNEL, O.FINAL_UTM_CAMPAIGN, O.FINAL_UTM_SOURCE, o.final_utm_term, o.final_utm_medium, O.Referrer_Name, O.CHECKOUT_MAPPED_SOURCE, O.CHECKOUT_MAPPED_CHANNEL, O.REFUND_DETAILS, O.AWB, UPPER(O.Courier) AS Courier, UPPER(O.Shipping_status) AS SHIPPING_STATUS, O.shipping_status_update_date, O.tracking_url, O.Shipping_created_at, O.GATEWAY, O.payment_mode, O.pincode, O.source_name, O.Location_ID, O.COD_FLAG, CASE WHEN O.cod_flag = 0 AND REGEXP_CONTAINS(UPPER(O.GATEWAY), r\'PPCOD\') THEN \'Partial Paid\' WHEN O.cod_flag = 1 THEN \'COD\' ELSE \'Prepaid\' END AS COD_PP_Flag, note_attributes FROM maplemonk.Shopify_hourly_All_orders_items O LEFT JOIN maplemonk.Shopify_All_products P ON O.PRODUCT_ID = JSON_VALUE(P.id, \'$\') LEFT JOIN (SELECT customer_id, city, province, ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY id DESC) AS rowid FROM maplemonk.Shopify_hourly_All_customers_addresses) AS CD ON JSON_EXTRACT_SCALAR(O.CUSTOMER, \'$.id\') = CAST(CD.customer_id AS STRING) AND rowid = 1; CREATE OR REPLACE TABLE maplemonk.beastlife_hourly_SHOPIFY_FACT_ITEMS_TEMP_Category as select fi.* ,coalesce(p.skucode,fi.SKU) AS SKU_CODE ,Upper(coalesce(p.name,fi.product_name)) as PRODUCT_NAME_Final ,coalesce(Upper(p.CATEGORY),upper(fi.category)) AS Product_Category ,Upper(p.sub_category) as Product_Sub_Category ,p.commonsku from maplemonk.beastlife_hourly_SHOPIFY_FACT_ITEMS_INTERMEDIATE fi left join (select * from (select skucode,null commonsku, name, cast(category as string) category, cast(null as string) as sub_category, row_number() over (partition by replace(skucode,\' \',\'\') order by 1) rw from maplemonk.sku_master ) where rw = 1 ) p on lower(replace(fi.sku,\' \',\'\')) = lower(replace(p.skucode,\' \',\'\')) ; CREATE OR REPLACE TABLE maplemonk.beastlife_hourly_SHOPIFY_FACT_ITEMS_INTERMEDIATE AS SELECT * FROM maplemonk.beastlife_hourly_SHOPIFY_FACT_ITEMS_TEMP_Category; CREATE OR REPLACE TABLE `maplemonk.beastlife_hourly_Shopify_Final_customerID` AS WITH new_phone_numbers AS ( SELECT phone, contact_num, 19700000000 + ROW_NUMBER() OVER (ORDER BY contact_num ASC) AS maple_monk_id FROM ( SELECT DISTINCT RIGHT(REGEXP_REPLACE(REPLACE(phone, \' \', \'\'), r\'[^a-zA-Z0-9]+\', \'\'), 10) AS contact_num, phone FROM `maplemonk.beastlife_hourly_SHOPIFY_FACT_ITEMS_INTERMEDIATE` ) a ), int AS ( SELECT contact_num, email, COALESCE(maple_monk_id, id2) AS maple_monk_id FROM ( SELECT contact_num, email, maple_monk_id, 19800000000 + ROW_NUMBER() OVER (PARTITION BY maple_monk_id IS NULL ORDER BY email ASC) AS id2 FROM ( SELECT DISTINCT COALESCE(p.contact_num, RIGHT(REGEXP_REPLACE(e.contact_num, r\'[^a-zA-Z0-9]+\', \'\'), 10)) AS contact_num, e.email, maple_monk_id FROM ( SELECT REPLACE(phone, \' \', \'\') AS contact_num, email FROM `maplemonk.beastlife_hourly_SHOPIFY_FACT_ITEMS_INTERMEDIATE` ) e LEFT JOIN new_phone_numbers p ON p.contact_num = RIGHT(REGEXP_REPLACE(e.contact_num, r\'[^a-zA-Z0-9]+\', \'\'), 10) ) a ) b ) SELECT contact_num, email, maple_monk_id FROM int WHERE COALESCE(contact_num, email) IS NOT NULL; CREATE OR REPLACE TABLE `maplemonk.beastlife_hourly_SHOPIFY_FACT_ITEMS` AS SELECT COALESCE(m.maple_monk_id_phone, d.maple_monk_id) AS Shopify_customer_id_final, MIN(CAST(ORDER_TIMESTAMP AS DATE)) OVER (PARTITION BY COALESCE(m.maple_monk_id_phone, d.maple_monk_id)) AS shopify_acquisition_date, MIN(CASE WHEN LOWER(order_status) NOT IN (\'cancelled\') THEN CAST(ORDER_TIMESTAMP AS DATE) END) OVER (PARTITION BY COALESCE(m.maple_monk_id_phone, d.maple_monk_id)) AS shopify_first_complete_order_date, m.* FROM ( SELECT c.maple_monk_id AS maple_monk_id_phone, o.* FROM `maplemonk.beastlife_hourly_SHOPIFY_FACT_ITEMS_INTERMEDIATE` o LEFT JOIN ( SELECT contact_num AS phone, maple_monk_id FROM ( SELECT contact_num, maple_monk_id, ROW_NUMBER() OVER (PARTITION BY contact_num ORDER BY maple_monk_id ASC) AS magic FROM `maplemonk.beastlife_hourly_Shopify_Final_customerID` ) WHERE magic = 1 ) c ON c.phone = RIGHT(REGEXP_REPLACE(o.phone, r\'[^a-zA-Z0-9]+\', \'\'), 10) ) m LEFT JOIN ( SELECT DISTINCT maple_monk_id, email FROM `maplemonk.beastlife_hourly_Shopify_Final_customerID` WHERE contact_num IS NULL ) d ON d.email = m.email; ALTER TABLE `maplemonk.beastlife_hourly_SHOPIFY_FACT_ITEMS` ADD COLUMN shopify_new_customer_flag STRING, ADD COLUMN shopify_new_customer_flag_month STRING, ADD COLUMN shopify_acquisition_product STRING, ADD COLUMN shopify_acquisition_channel STRING, ADD COLUMN shopify_acquisition_source STRING; UPDATE `maplemonk.beastlife_hourly_SHOPIFY_FACT_ITEMS` AS A SET A.shopify_new_customer_flag = B.flag FROM ( SELECT DISTINCT order_id, Shopify_customer_id_final, ORDER_TIMESTAMP, CASE WHEN DATE(ORDER_TIMESTAMP) = shopify_first_complete_order_date THEN \'New\' WHEN DATE(ORDER_TIMESTAMP) < shopify_first_complete_order_date OR shopify_first_complete_order_date IS NULL THEN \'Yet to make completed order\' WHEN DATE(ORDER_TIMESTAMP) > shopify_first_complete_order_date THEN \'Repeat\' END AS flag FROM `maplemonk.beastlife_hourly_SHOPIFY_FACT_ITEMS` ) AS B WHERE A.order_id = B.order_id AND A.Shopify_customer_id_final = B.Shopify_customer_id_final AND DATE(A.ORDER_TIMESTAMP) = DATE(B.ORDER_TIMESTAMP); UPDATE `maplemonk.beastlife_hourly_SHOPIFY_FACT_ITEMS` SET shopify_new_customer_flag = CASE WHEN shopify_new_customer_flag IS NULL AND (CASE WHEN LOWER(order_status) IS NULL THEN TRUE ELSE LOWER(order_status) NOT IN (\'cancelled\') END) THEN \'New\' WHEN shopify_new_customer_flag IS NULL AND (CASE WHEN LOWER(order_status) IS NULL THEN TRUE ELSE LOWER(order_status) IN (\'cancelled\') END) THEN \'Yet to make completed order\' ELSE shopify_new_customer_flag END where true; UPDATE `maplemonk.beastlife_hourly_SHOPIFY_FACT_ITEMS` AS A SET A.shopify_new_customer_flag_month = B.flag FROM ( SELECT DISTINCT order_id, shopify_customer_id_final, DATE(ORDER_TIMESTAMP) AS Order_Date, CASE WHEN LAST_DAY(DATE(ORDER_TIMESTAMP)) = LAST_DAY(DATE(shopify_first_complete_order_date)) THEN \'New\' WHEN LAST_DAY(DATE(ORDER_TIMESTAMP)) < LAST_DAY(DATE(shopify_first_complete_order_date)) OR shopify_acquisition_date IS NULL THEN \'Yet to make completed order\' WHEN LAST_DAY(DATE(ORDER_TIMESTAMP)) > LAST_DAY(DATE(shopify_first_complete_order_date)) THEN \'Repeat\' END AS Flag FROM `maplemonk.beastlife_hourly_SHOPIFY_FACT_ITEMS` ) AS B WHERE A.order_id = B.order_id AND A.shopify_customer_id_final = B.shopify_customer_id_final; UPDATE `maplemonk.beastlife_hourly_SHOPIFY_FACT_ITEMS` SET shopify_new_customer_flag_month = CASE WHEN shopify_new_customer_flag_month IS NULL AND (CASE WHEN LOWER(order_status) IS NULL THEN TRUE ELSE LOWER(order_status) NOT IN (\'cancelled\') END) THEN \'New\' ELSE shopify_new_customer_flag_month END WHERE true; CREATE OR REPLACE TABLE `maplemonk.hourly_temp_source_1` AS SELECT shopify_customer_id_final, channel, source FROM ( SELECT DISTINCT shopify_customer_id_final, DATE(order_timestamp) AS order_Date, FINAL_UTM_SOURCE AS SOURCE, FINAL_UTM_CHANNEL AS CHANNEL, MIN(CASE WHEN LOWER(order_status) NOT IN (\'cancelled\') THEN DATE(order_timestamp) END) OVER (PARTITION BY shopify_customer_id_final) AS firstOrderdate, row_number() over(partition by shopify_customer_id_final order by 1 desc) rw FROM `maplemonk.beastlife_hourly_SHOPIFY_FACT_ITEMS` ) res WHERE order_Date = firstOrderdate and rw = 1; UPDATE `maplemonk.beastlife_hourly_SHOPIFY_FACT_ITEMS` AS a SET a.shopify_acquisition_channel = b.channel FROM `maplemonk.hourly_temp_source_1` b WHERE a.shopify_customer_id_final = b.shopify_customer_id_final; UPDATE `maplemonk.beastlife_hourly_SHOPIFY_FACT_ITEMS` AS a SET a.shopify_acquisition_source = b.source FROM `maplemonk.hourly_temp_source_1` b WHERE a.shopify_customer_id_final = b.shopify_customer_id_final; CREATE OR REPLACE TABLE `maplemonk.hourly_temp_product_1` AS SELECT DISTINCT shopify_customer_id_final, product_name_final, ROW_NUMBER() OVER (PARTITION BY shopify_customer_id_final ORDER BY total_sales DESC) AS rowid FROM ( SELECT DISTINCT shopify_customer_id_final, CAST(order_timestamp AS DATE) AS order_date, product_name_final, total_sales, MIN(CASE WHEN LOWER(order_status) NOT IN (\'cancelled\') THEN CAST(order_timestamp AS DATE) END) OVER (PARTITION BY shopify_customer_id_final) AS firstOrderdate FROM `maplemonk.beastlife_hourly_SHOPIFY_FACT_ITEMS` ) res WHERE order_date = firstOrderdate; UPDATE maplemonk.beastlife_hourly_SHOPIFY_FACT_ITEMS AS A SET A.shopify_acquisition_product=B.product_name_final FROM ( SELECT * FROM maplemonk.hourly_temp_product_1 WHERE rowid=1)B WHERE A.shopify_customer_id_final = B.shopify_customer_id_final; ALTER TABLE `maplemonk.beastlife_hourly_SHOPIFY_FACT_ITEMS` ADD COLUMN SHIPPING_TAX FLOAT64, ADD COLUMN SHIP_PROMOTION_DISCOUNT FLOAT64, ADD COLUMN GIFT_WRAP_PRICE FLOAT64, ADD COLUMN GIFT_WRAP_TAX FLOAT64;",
